/// <summary>
/// AVA_007510_SumLedgerAccounts update RuleSources after Update on SumAccount
/// </summary>
[ExtensionOf(tableStr(DimensionAttributeValueTotallingCriteria))]
final class AVADimensionAttributeValueTotallingCriteria_Extension
{
}

Method.Source:
public void delete()
{
    next delete();
    this.AVAupdateLedgerAllocRules();
}

public void update()
{
    next update();
    this.AVAupdateLedgerAllocRules();
}

public void insert()
{
    next insert();
    this.AVAupdateLedgerAllocRules();
}

private void AVAupdateLedgerAllocRules(RefRecId _dimAttributeValue = this.DimensionAttributeValue)
{
    MainAccount                                 mainAccount;
    DimensionAttributeValue                     dimensionAttributeValue;
    DimensionAttributeValueTotallingCriteria    totallingCriteria;
    LedgerAllocationRuleSource                  ruleSource;
    LedgerAllocationBasisRuleSource             basisRuleSource;

    select firstonly dimensionAttributeValue
         where dimensionAttributeValue.RecId == _dimAttributeValue
            && dimensionAttributeValue.DimensionAttribute == DimensionAttribute::getWellKnownDimensionAttribute(DimensionAttributeType::MainAccount)
        join MainAccount where MainAccount.RecId == dimensionAttributeValue.EntityInstance
        && mainAccount.Type == DimensionLedgerAccountType::Total;
    if (mainAccount.MainAccountId)
    {
        while select forupdate ruleSource where ruleSource.FieldSetting == LedgerAllocationAccountDimension::SumAccount
                                            && ruleSource.SourceCriteria == mainAccount.MainAccountId
        {
            ruleSource.update();
        }
        while select forupdate basisRuleSource where basisRuleSource.FieldSetting == LedgerAllocationAccountDimension::SumAccount
                                            && basisRuleSource.BasisCriteria == mainAccount.MainAccountId
        {
            basisRuleSource.update();
        }
        while select totallingCriteria
            where mainAccount.MainAccountId >= totallingCriteria.FromValue
                && mainAccount.MainAccountId <= totallingCriteria.ToValue
        {
            select firstonly dimensionAttributeValue
                     where dimensionAttributeValue.RecId == totallingCriteria.DimensionAttributeValue
                        && dimensionAttributeValue.DimensionAttribute == DimensionAttribute::getWellKnownDimensionAttribute(DimensionAttributeType::MainAccount)
                    join MainAccount where MainAccount.RecId == dimensionAttributeValue.EntityInstance
                    && mainAccount.Type == DimensionLedgerAccountType::Total;
            if (mainAccount.MainAccountId)
            {
                while select forupdate ruleSource where ruleSource.FieldSetting == LedgerAllocationAccountDimension::SumAccount
                                            && ruleSource.SourceCriteria == mainAccount.MainAccountId
                {
                    ruleSource.update();
                }
                while select forupdate basisRuleSource where basisRuleSource.FieldSetting == LedgerAllocationAccountDimension::SumAccount
                                            && basisRuleSource.BasisCriteria == mainAccount.MainAccountId
                {
                    basisRuleSource.update();
                }
            }
        }
    }
}
